#include "crt.h"
// Run-length encode a generated byte stream (runs capped at 255), decode it back, compare, checksum the encoding.
#define LEN 1500
static unsigned char src[LEN], enc[2 * LEN], dec[LEN];
static int encode(const unsigned char *in, int n, unsigned char *out) {
    int o = 0, i = 0;
    while (i < n) {
        unsigned char b = in[i];
        int r = 1;
        while (i + r < n && in[i + r] == b && r < 255) ++r;
        out[o++] = (unsigned char)r;
        out[o++] = b;
        i += r;
    }
    return o;
}
static int decode(const unsigned char *in, int n, unsigned char *out) {
    int o = 0;
    for (int i = 0; i + 1 < n; i += 2)
        for (int r = 0; r < in[i]; ++r) out[o++] = in[i + 1];
    return o;
}
int cmain(void) {
    unsigned x = 2024;
    int i = 0;
    while (i < LEN) {
        x ^= x << 13; x ^= x >> 17; x ^= x << 5;
        int run = 1 + (int)(x % 9) + ((x >> 9) % 7 == 0 ? 300 : 0);
        unsigned char b = (unsigned char)(x >> 24);
        while (run-- && i < LEN) src[i++] = b;
    }
    int e = encode(src, LEN, enc);
    int d = decode(enc, e, dec);
    u64 same = (u64)(d == LEN), h = 1469598103934665603ull;
    for (int k = 0; k < LEN; ++k) same &= (u64)(src[k] == dec[k]);
    for (int k = 0; k < e; ++k) h = (h ^ enc[k]) * 1099511628211ull;
    put_u64((u64)e); put_u64(same); put_u64(h);
    return 0;
}
